from .kalender import _ergebnis, _text, _auswahl
from .betraege import _geld, _wahrheitswert
from .zahlen import _bruch, _addieren, _subtrahieren, _multiplizieren
from .zinsen import _bruchteile

def vergleichsmiete_ausgleich_und_drittmittel(ausgangsmiete_drei_jahre=None, nicht_anzurechnende_erhoehungen=None, derzeitige_monatsmiete=None, ortsuebliche_vergleichsmiete=None, gueltige_fuenfzehnprozent_verordnung=None, kapitalzuschuesse_559a_1=None, jaehrliche_zinsermaessigung=None, jaehrliche_laufende_foerderung=None, letzte_monatliche_ausgleichszahlung=None, ausnahmemodell=None, methodennachweis=None):
    """558V-Förderabzug berechnen und bereinigte Vergleichsmiete mit zwei ausdrücklich qualifizierten558IV-Kappungsmodellen verbinden."""
    basis=_geld(ausgangsmiete_drei_jahre);aus=_geld(nicht_anzurechnende_erhoehungen);alt=_geld(derzeitige_monatsmiete);v=_geld(ortsuebliche_vergleichsmiete);fuenfzehn=_wahrheitswert(gueltige_fuenfzehnprozent_verordnung,'gueltige_fuenfzehnprozent_verordnung');z=_geld(kapitalzuschuesse_559a_1);zins=_geld(jaehrliche_zinsermaessigung);laufend=_geld(jaehrliche_laufende_foerderung);a=_geld(letzte_monatliche_ausgleichszahlung);_text(methodennachweis,'methodennachweis');_auswahl(ausnahmemodell,'ausnahmemodell',('alternative_erhoehungsgrenze','zusaetzlicher_ausnahmebetrag'))
    abzug=_addieren(_addieren(_multiplizieren(z,_bruch(2,25)),zins),laufend);vergleich=max(_subtrahieren(v,_multiplizieren(abzug,_bruch(1,12))),_bruch(0))
    kappung=_addieren(_multiplizieren(basis,_bruch(115 if fuenfzehn else 120,100)),aus);spielraum=max(_subtrahieren(kappung,alt),_bruch(0))
    alternativ=max(alt,min(vergleich,_addieren(alt,max(spielraum,a))));additiv=max(alt,min(vergleich,_addieren(_addieren(alt,spielraum),a)));wahl=alternativ if ausnahmemodell=='alternative_erhoehungsgrenze' else additiv
    wert=dict(jaehrlicher_drittmittelabzug=_bruchteile(abzug),vergleichsmiete_nach_drittmitteln=_bruchteile(vergleich),monatsmiete_alternativmodell=_bruchteile(alternativ),monatsmiete_additionsmodell=_bruchteile(additiv),monatsmiete_nach_vorgegebenem_modell=_bruchteile(wahl),erhoehungsbetrag=_bruchteile(_subtrahieren(wahl,alt)))
    eingaben = dict(ausgangsmiete_drei_jahre=ausgangsmiete_drei_jahre, nicht_anzurechnende_erhoehungen=nicht_anzurechnende_erhoehungen, derzeitige_monatsmiete=derzeitige_monatsmiete, ortsuebliche_vergleichsmiete=ortsuebliche_vergleichsmiete, gueltige_fuenfzehnprozent_verordnung=gueltige_fuenfzehnprozent_verordnung, kapitalzuschuesse_559a_1=kapitalzuschuesse_559a_1, jaehrliche_zinsermaessigung=jaehrliche_zinsermaessigung, jaehrliche_laufende_foerderung=jaehrliche_laufende_foerderung, letzte_monatliche_ausgleichszahlung=letzte_monatliche_ausgleichszahlung, ausnahmemodell=ausnahmemodell, methodennachweis=methodennachweis)
    ergebnis = _ergebnis(wert,'EUR','BGB_VERGLEICHSMIETE_AUSGLEICH_UND_DRITTMITTEL',eingaben,[dict(operation='558V-Förderabzug berechnen und bereinigte Vergleichsmiete mit zwei ausdrücklich qualifizierten558IV-Kappungsmodellen verbinden.')],eingaben.copy())
    ergebnis["hinweise"] = ['558V:8%der559aI-Zuschüsse plus jährliche Zinsermäßigung und laufende Förderbeträge vom Jahresbetrag der Vergleichsmiete abziehen, für Monatsgrenze durch12. Nicht den Zuschuss selbst als Jahresabzug und nicht nochmals von bereits bereinigter Vergleichsmiete abziehen. Reguläre Kappung aus Dreijahresbasis*1.15oder1.20plusausgenommenen Erhöhungen.558IV-Konkurrenz rechtlich zwingend wählen: alternativeErhöhungsgrenze=max(regulärer positiver Erhöhungsspielraum,Ausgleichszahlung); zusätzlicherAusnahmebetrag=regulärer positiver Spielraum+Ausgleichszahlung. Beide bedingten Wege werden ausgewiesen, keine allgemein bestätigte Addition behauptet. Vergleichsmiete nach Förderung bleibt in beiden Varianten Obergrenze. Bereits darüber liegende Bestandsmiete wird nicht automatisch gesenkt; nur positiver neuer Erhöhungsbetrag. Antwort-/Vorlauffristen und Wirksamkeit gesondert.']
    return ergebnis

